package com.settlement.rail.cycle;

import jakarta.persistence.*;
import lombok.*;

import java.time.Instant;

/**
 * A settlement cycle. Its own surrogate primary key ({@link #id}) IS the
 * cycle identifier used everywhere else in the application (ledger entries,
 * transfers, settlements, job parameters) — a plain incrementing number
 * generated by the database, no separate business identifier needed.
 * <p>
 * Lifecycle: exactly one cycle is ever OPEN at a time (new transactions are
 * tagged with it). {@code SettlementCycleService.rotateCycle()} moves it to
 * PROCESSING and opens the next OPEN cycle; once the settlement job for it
 * completes successfully it is marked CLOSED.
 */
@Entity
@Table(
        name = "settlement_cycles",
        indexes = {
                @Index(name = "idx_settlement_cycle_status", columnList = "status"),
                @Index(name = "idx_settlement_cycle_start_time", columnList = "start_time")
        }
)
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class SettlementCycle {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "start_time", nullable = false)
    private Instant startTime;

    @Column(name = "end_time")
    private Instant endTime;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false, length = 20)
    private SettlementCycleStatus status;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @Column(name = "updated_at")
    private Instant updatedAt;

    @PrePersist
    void prePersist() {
        Instant now = Instant.now();
        this.createdAt = now;
        this.updatedAt = now;
        if (this.startTime == null) {
            this.startTime = now;
        }
        if (this.status == null) {
            this.status = SettlementCycleStatus.OPEN;
        }
    }

    @PreUpdate
    void preUpdate() {
        this.updatedAt = Instant.now();
    }
}
